export interface ConnectorConfig {
  mailchimpApiKey: string;
  datadogApiKey: string;
  datadogSite: string;
  fetch?: typeof fetch;
}

export interface MailchimpRetryPayload {
  response_status: number;
  retry_count: number;
  final_response_body: string;
  retry_after_header: string;
}

export interface HandleResult {
  eventId: string;
}

export async function handle(
  payload: MailchimpRetryPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  if (payload.response_status === undefined || payload.response_status === null) {
    throw new Error('Missing required field: response_status');
  }
  if (payload.retry_count === undefined || payload.retry_count === null) {
    throw new Error('Missing required field: retry_count');
  }
  if (payload.final_response_body === undefined || payload.final_response_body === null) {
    throw new Error('Missing required field: final_response_body');
  }
  if (payload.retry_after_header === undefined || payload.retry_after_header === null) {
    throw new Error('Missing required field: retry_after_header');
  }

  const fetchImpl = config.fetch ?? fetch;

  const status = payload.response_status === 429 ? 'error' : 'success';

  const datadogPayload = {
    title: 'Mailchimp API Retry Outcome',
    text: `Final response body: ${payload.final_response_body}`,
    tags: [
      `retry_after:${payload.retry_after_header}`,
      `retry_count:${payload.retry_count}`,
      `status:${status}`
    ],
    timestamp: Math.floor(Date.now() / 1000)
  };

  const url = `https://event-management-intake.${config.datadogSite}/api/v2/events`;

  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'DD-API-KEY': config.datadogApiKey
    },
    body: JSON.stringify(datadogPayload)
  });

  if (!response.ok) {
    throw new Error(`Datadog Events API request failed with status ${response.status} at ${url}`);
  }

  const data = await response.json() as { event: { id: string } };
  return { eventId: data.event.id };
}

