    const { fetch, calls } = fakeFetch((req) => {
      expect(req.headers.get('dd-api-key')).toBe('my-datadog-key');
      return jsonResponse({ event: { id: 'evt-456' } }, 201);
    });

    const payload: MailchimpRetryPayload = {
      response_status: 429,
      retry_count: 0,
      final_response_body: '{}',
      retry_after_header: '30'
    };

    await handle(payload, { ...baseConfig, datadogApiKey: 'my-datadog-key', fetch });
    expect(calls[0].headers.get('dd-api-key')).toBe('my-datadog-key');
  });

  it('maps fields correctly including status success when not 429', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      const body = req.json as Record<string, unknown>;
      expect(body.tags).toContain('status:success');
      return jsonResponse({ event: { id: 'evt-789' } }, 201);
    });

    const payload: MailchimpRetryPayload = {
      response_status: 200,
      retry_count: 1,
      final_response_body: '{"success":true}',
      retry_after_header: '0'
    };

    await handle(payload, { ...baseConfig, fetch });
    expect(calls.length).toBe(1);
