      response_status: 429,
      retry_count: 1,
      retry_after_header: '30'
    } as unknown as MailchimpRetryPayload;

    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: final_response_body');
  });

  it('throws descriptive error when retry_after_header is missing', async () => {
    const payload = {
      response_status: 429,
      retry_count: 1,
      final_response_body: '{}'
    } as unknown as MailchimpRetryPayload;

    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: retry_after_header');
  });

  it('throws error with status and endpoint on non-2xx response', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'unauthorized' }, 401));

    const payload: MailchimpRetryPayload = {
      response_status: 429,
      retry_count: 1,
      final_response_body: '{}',
      retry_after_header: '30'
    };

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'Datadog Events API request failed with status 401 at https://event-management-intake.datadoghq.com/api/v2/events'
    );
    expect(calls.length).toBe(1);
  });

  it('uses custom datadogSite in URL', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.url).toBe('https://event-management-intake.us3.datadoghq.com/api/v2/events');
      return jsonResponse({ event: { id: 'evt-site' } }, 201);
